L23_1.m_Talk_KOREA = "뻔하잖아. 애초에 다른 세계에서 도망쳐 온 엑자일러가 튀어봤자 어디로 튀겠어?"
L23_1.m_fTalkTime = 0.03
L23_1.m_Talk_JPN = "決まってるでしょ？　他の世界から逃げてきたエグザイラーが隠れそうな場所って言えばさ。"
L23_1.m_Talk_ENG = "Isn't it obvious? If an Exile from another world was running away, where do you think they'd go?"
L23_1.m_Talk_TWN = "這不明顯嗎？如果一個來自其他世界的流浪者逃跑，他們會去哪？"
L23_1.m_Talk_SCN = "显而易见。最初从其他世界逃来的流浪者，就算逃跑又能逃到哪里去呢？"
L23_1.m_Talk_DEU = "Isn't it obvious? If an Exile from another world was running away, where do you think they'd go?"
L23_1.m_Talk_FRA = "Isn't it obvious? If an Exile from another world was running away, where do you think they'd go?"
