L25_1 = {}
L25_1.m_CutScenKey_Talk = "EP13_ACT3_STAGE1_END@14#Talk"
L25_1.m_CutScenProcessKey = 25
L25_1.m_CutScenID = 603
L25_1.m_CutScenStrID = "EP13_ACT3_STAGE1_END"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L25_1.m_CharStrID = "YOOMINA_FENRIR_NULL_NULL"
L25_1.m_Pos = "R"
L25_1.m_Talk_KOREA = "그럼, 설마 여기가 스완의 고향 세계라는 거야?"
L25_1.m_fTalkTime = 0.03
L25_1.m_Talk_JPN = "じゃあ、まさかここがスワンの故郷ってこと？"
L25_1.m_Talk_ENG = "Wait, you're saying this is Swan's home world?"
L25_1.m_Talk_TWN = "等等，你是說這是史旺的家鄉世界？"
L25_1.m_Talk_SCN = "那么，难道这里就是斯旺的故乡世界吗？"
L25_1.m_Talk_DEU = "Wait, you're saying this is Swan's home world?"
L25_1.m_Talk_FRA = "Wait, you're saying this is Swan's home world?"
L26_1 = {}
L26_1.m_CutScenKey_Talk = "EP13_ACT3_STAGE1_END@15#Talk"
L26_1.m_CutScenProcessKey = 26
L26_1.m_CutScenID = 603
L26_1.m_CutScenStrID = "EP13_ACT3_STAGE1_END"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L26_1.m_Face = "UNIT_IDLE"
L26_1.m_CharStrID = "AMY_SIX_NULL_NULL"
L26_1.m_Pos = "L"
L26_1.m_Talk_KOREA = "그래, 육익의 동료 중에는 과거를 통찰하는 능력을 가진 녀석이 있거든."
L26_1.m_fTalkTime = 0.03
L26_1.m_Talk_JPN = "そう。六翼の仲間には過去を見通す能力を持ってるやつがいるんだよ。"
L26_1.m_Talk_ENG = "Yeah. One of my comrades at Six Wings has the power to perceive the past."
L26_1.m_Talk_TWN = "沒錯。六翼的一位同伴有感知過去的能力。"
L26_1.m_Talk_SCN = "是啊，六翼的同伴中有个可以洞察过去的能力的家伙。"
L26_1.m_Talk_DEU = "Yeah. One of my comrades at Six Wings has the power to perceive the past."
L26_1.m_Talk_FRA = "Yeah. One of my comrades at Six Wings has the power to perceive the past."
L27_1 = {}
L27_1.m_CutScenKey_Talk = "EP13_ACT3_STAGE1_END@16#Talk"
L27_1.m_CutScenProcessKey = 27
L27_1.m_CutScenID = 603
L27_1.m_CutScenStrID = "EP13_ACT3_STAGE1_END"
L27_1.m_bWaitClick = true
