L27_1.m_CharStrID = "AMY_SIX_NULL_NULL"
L27_1.m_Pos = "L"
L27_1.m_Talk_KOREA = "그 녀석이 알려준 스완의 고향 세계 좌표가 바로 여기야."
L27_1.m_fTalkTime = 0.03
L27_1.m_Talk_JPN = "そいつが教えてくれたスワンの故郷の座標がここってわけ。"
L27_1.m_Talk_ENG = "The coordinates she pinpointed are here, Swan's home world."
L27_1.m_Talk_TWN = "她定位的座標就在這裡，史旺的家鄉世界。"
L27_1.m_Talk_SCN = "那家伙告诉我斯旺故乡的世界坐标就在这里。"
L27_1.m_Talk_DEU = "The coordinates she pinpointed are here, Swan's home world."
L27_1.m_Talk_FRA = "The coordinates she pinpointed are here, Swan's home world."
