L29_1.m_Talk_KOREA = "잠깐만 이곳이 이면세계라는 건, 스완의 세계가 이미 멸망해 버렸다는 뜻이잖아."
L29_1.m_fTalkTime = 0.03
L29_1.m_Talk_JPN = "待って。ここが裏世界だってことは、スワンの世界がもう滅亡してしまったってことじゃない。"
L29_1.m_Talk_ENG = "Hold on. If this place is part of the Counterside, doesn't that mean Swan's world was already destroyed?"
L29_1.m_Talk_TWN = "等等，如果這地方是異界的一部分，那不就代表史旺的世界早已被毀？"
L29_1.m_Talk_SCN = "等一下，这里是异界，那就意味着斯旺的世界已经灭亡了。"
