L44_1 = "하지만 스완은 처음부터 그곳이 세피라와 접촉할 수 있는 장소라는 걸 알고 있었어."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "でもスワンは最初からそこがセフィラと接触できる場所だって知ってたんだよ。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "But Swan knew from the start that it was a place where she could contact Sephira."
L43_1.m_Talk_ENG = L44_1
L44_1 = "但史旺從一開始就知道，那是她能接觸生命樹的地方。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "但是斯旺从一开始就知道那里是可以与塞菲拉接触的地方。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "But Swan knew from the start that it was a place where she could contact Sephira."
L43_1.m_Talk_DEU = L44_1
L44_1 = "But Swan knew from the start that it was a place where she could contact Sephira."
L43_1.m_Talk_FRA = L44_1
