L45_1 = "EP13_ACT3_STAGE1_END@27#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 44
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 603
L44_1.m_CutScenStrID = "EP13_ACT3_STAGE1_END"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L44_1.m_CharStrID = "AMY_SIX_NULL_NULL"
L45_1 = "게임이 끝나는 순간, 개기일식이 발생했고 우리는 그곳에서 달의 뒷면을 목격했지."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "ゲームが終わる瞬間に皆既日食が始まって、あたしらはそこで月の裏側を目撃した。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "As soon as the game ended, a total solar eclipse occurred, and we saw the dark side of the moon."
L44_1.m_Talk_ENG = L45_1
L45_1 = "遊戲結束的瞬間，發生了日全蝕，我們看到了月球的背面。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "战役结束的瞬间，发生了日全食，我们在那里目睹了月亮的背面。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "As soon as the game ended, a total solar eclipse occurred, and we saw the dark side of the moon."
L44_1.m_Talk_DEU = L45_1
L45_1 = "As soon as the game ended, a total solar eclipse occurred, and we saw the dark side of the moon."
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
L46_1 = "EP13_ACT3_STAGE1_END@28#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 45
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 603
L45_1.m_CutScenStrID = "EP13_ACT3_STAGE1_END"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L45_1.m_CharStrID = "AMY_SIX_NULL_NULL"
L46_1 = "그리고 달에서부터 엄청난 에너지 반응이 방출되는 순간, 세계가 바뀌었어."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "そして月からものすごいエネルギー反応が放出された瞬間、世界が変わったんだ。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "And at the moment a massive energy surge was emitted from the moon, the world changed."
L45_1.m_Talk_ENG = L46_1
L46_1 = "就在月球釋放出巨大能量波的那刻，世界變了樣。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "当从月球释放出巨大的能量反应时，世界发生了改变。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "And at the moment a massive energy surge was emitted from the moon, the world changed."
L45_1.m_Talk_DEU = L46_1
L46_1 = "And at the moment a massive energy surge was emitted from the moon, the world changed."
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
