L3_1 = "맞아. 현실 개변이 발생한 순간, 우리가 있던 침식지대가 울창한 숲으로 바뀌었어."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "そう。現実改変が発生した瞬間、あたしらがいた侵食地帯がうっそうとした森になった。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "That's right. The moment the change in reality occurred, the Corrupted Area we were in turned into a lush forest."
L2_1.m_Talk_ENG = L3_1
L3_1 = "沒錯。現實改變發生的瞬間，我們所在的侵蝕地帶變成了一片茂密的森林。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "没错。现实改变的瞬间，我们所在的侵蚀地带变成了郁郁葱葱的森林。"
L2_1.m_Talk_SCN = L3_1
L3_1 = "That's right. The moment the change in reality occurred, the Corrupted Area we were in turned into a lush forest."
L2_1.m_Talk_DEU = L3_1
L3_1 = "That's right. The moment the change in reality occurred, the Corrupted Area we were in turned into a lush forest."
L2_1.m_Talk_FRA = L3_1
