L3_1.m_CharStrID = "AMY_SIX_NULL_NULL"
L4_1 = "침식파에 의해 오염된 땅이 원래대로 자연을 회복하려면 오랜 시간이 걸리지."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "侵食波によって汚染された土地が元どおりに自然を回復するには長い時間がかかる。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "Usually, it takes a long time for land tainted by Corruption rays to recover."
L3_1.m_Talk_ENG = L4_1
L4_1 = "通常被侵蝕波污染的土地需要很長時間才能恢復。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "被侵蚀波污染的土地要恢复到原来的自然状态需要很长时间。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Usually, it takes a long time for land tainted by Corruption rays to recover."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Usually, it takes a long time for land tainted by Corruption rays to recover."
L3_1.m_Talk_FRA = L4_1
