L10_1 = "그 뒤로 스완에게 뒤통수를 맞아서, 자세한 정황까지는 나도 잘 모르지만……."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "それからはスワンに裏切られて、詳しい状況まではあたしもよくわかんないけど……"
L9_1.m_Talk_JPN = L10_1
L10_1 = "After that, Swan stabbed me in the back, so I don't know all the details, but..."
L9_1.m_Talk_ENG = L10_1
L10_1 = "之後史旺背叛了我，所以我不清楚所有細節，但…"
L9_1.m_Talk_TWN = L10_1
L10_1 = "之后被斯旺暗算，具体情况我也不太清楚……"
L9_1.m_Talk_SCN = L10_1
L10_1 = "After that, Swan stabbed me in the back, so I don't know all the details, but..."
