L11_1 = "얼마간 시간이 지난 뒤에 다시 그곳을 찾았을 때, 숲 같은 건 어디에도 없었거든."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "しばらくしてからまたそこに行った時には、森なんてどこにもなかったんだよね。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "When I went back to that place after some time, there was no forest."
L10_1.m_Talk_ENG = L11_1
L11_1 = "過了一段時間我再回到那裡，森林已不復存在。"
L10_1.m_Talk_TWN = L11_1
L11_1 = "过了一段时间再次去那里时，发现森林已经不复存在了。"
L10_1.m_Talk_SCN = L11_1
L11_1 = "When I went back to that place after some time, there was no forest."
L10_1.m_Talk_DEU = L11_1
L11_1 = "When I went back to that place after some time, there was no forest."
L10_1.m_Talk_FRA = L11_1
