L12_1 = "즉, <color=#ffd34c>모종의 이유</color>로 인해, 그곳은 다시 침식지대로 되돌아간 거지."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "つまり、<color=#ffd34c>ある理由</color>であそこはまた侵食地帯に戻ったわけ。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "In other words, <color=#ffd34c>for some reason</color>, the area reverted to a Corrupted Area."
L11_1.m_Talk_ENG = L12_1
L12_1 = "換句話說，<color=#ffd34c>不知為何</color>那區域又變回了侵蝕地帶。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "也就是说，<color=#ffd34c>由于某种原因</color>，那里又变回了侵蚀之地。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "In other words, <color=#ffd34c>for some reason</color>, the area reverted to a Corrupted Area."
L11_1.m_Talk_DEU = L12_1
L12_1 = "In other words, <color=#ffd34c>for some reason</color>, the area reverted to a Corrupted Area."
