L22_1.m_Pos = "L"
L22_1.m_Crash = 10
L23_1 = "틀림없이 이면세계가 되어버린 자기 고향 세계를 되돌리려고 할 거야."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "間違いなく裏世界になってしまった自分の故郷を元に戻そうとするはずだ。"
