L24_1.m_Pos = "C"
L25_1 = "문제는 그 세피라에 의한 현실 개변이라는 게, 어디까지 가능한 건지 모른다는 거지."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "問題はそのセフィラによる現実改変ってやつがどこまで可能なのかが未知数だってこと。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "The problem is, we still don't know how far this change in reality caused by Sephira can go."
L24_1.m_Talk_ENG = L25_1
L25_1 = "問題是，我們還不知道生命樹引起的現實改變能達到什麼程度。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "问题在于，由于那个塞菲拉引起的现实改变不知道究竟能达到什么程度。"
