L34_1 = "USER_ADMIN_NULL_NULL"
L33_1.m_CharStrID = L34_1
L34_1 = "하지만 기록에 따르면, 노엘 양은 이미 20년 전, 전쟁으로 인해 죽은 소녀라네."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "しかし記録によると、ノエル君はすでに20年前、戦争で命を落としているらしい。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "But the records say she died in a war twenty years ago."
