L33_1.m_CharStrID = "AMY_SIX_NULL_NULL"
L33_1.m_Pos = "L"
L34_1 = "그래, 마침 잘 됐다! 이 경찰 아저씨들한테 스완이 어디 있는지 물어보면 되겠네!"
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "そうだ、ちょうどよかった！　この警官たちにスワンがどこにいるのか聞いてみよう！"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Great, just what I needed! We can ask these officers where Swan is hiding!"
L33_1.m_Talk_ENG = L34_1
L34_1 = "太好了，正合我意！我們可以問問這些警察史旺藏在哪裡！"
L33_1.m_Talk_TWN = L34_1
L34_1 = "好，正好！可以问这些警察叔叔们斯旺在哪里！"
