L35_1.m_Pos = "R"
L36_1 = "진정 좀 해! 네 말이 맞다고 해도, 굳이 이렇게 소란을 피울 필요는 없잖아!"
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "落ち着いてよ！　あなたの言うとおりだとしても、ここまで事を大きくする必要なんてないでしょ！"
L35_1.m_Talk_JPN = L36_1
L36_1 = "Calm down! Even if you're right, there's no reason to make a scene here!"
L35_1.m_Talk_ENG = L36_1
L36_1 = "冷靜點！就算你說得沒錯，這裡也沒必要鬧事！"
L35_1.m_Talk_TWN = L36_1
L36_1 = "冷静点！即使你说得对，也没必要这么大吵大闹吧！"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Calm down! Even if you're right, there's no reason to make a scene here!"
L35_1.m_Talk_DEU = L36_1
L36_1 = "Calm down! Even if you're right, there's no reason to make a scene here!"
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "EP13_ACT3_STAGE1_END@113#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 186
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 603
L36_1.m_CutScenStrID = "EP13_ACT3_STAGE1_END"
