L36_1.m_fWaitTime = 0
L36_1.m_CharStrID = "YOOMINA_FENRIR_NULL_NULL"
L36_1.m_Pos = "R"
L37_1 = "일단은 여길 빠져나가서 도시에 대한 정보를 수집하는 게 먼저라고……!"
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "いったんここから逃げて、都市の情報を集めるのが先だって……！"
L36_1.m_Talk_JPN = L37_1
L37_1 = "We need to get out of here and gather more information about this city first...!"
L36_1.m_Talk_ENG = L37_1
L37_1 = "我們得先離開這裡，蒐集更多關於這座城市的情報……！"
L36_1.m_Talk_TWN = L37_1
L37_1 = "首先要先离开这里，收集关于城市的信息才是正事！"
L36_1.m_Talk_SCN = L37_1
L37_1 = "We need to get out of here and gather more information about this city first...!"
L36_1.m_Talk_DEU = L37_1
L37_1 = "We need to get out of here and gather more information about this city first...!"
L36_1.m_Talk_FRA = L37_1
