L37_1.m_CharStrID = "AMY_SIX_NULL_NULL"
L37_1.m_Pos = "L"
L37_1.m_Crash = 20
L38_1 = "그러니까 그걸 이 자식들 족치고 물어보면 되잖아!"
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "だから、それをこいつら叩いて聞いてみればいいじゃないか！"
L37_1.m_Talk_JPN = L38_1
L38_1 = "Exactly. We rough these guys up and get them to talk!"
L37_1.m_Talk_ENG = L38_1
L38_1 = "沒錯，先把他們揍一頓再逼他們說話！"
L37_1.m_Talk_TWN = L38_1
L38_1 = "所以只要抓住这些家伙问清楚就行了！"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Exactly. We rough these guys up and get them to talk!"
L37_1.m_Talk_DEU = L38_1
L38_1 = "Exactly. We rough these guys up and get them to talk!"
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
