L39_1 = 188
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 603
L38_1.m_CutScenStrID = "EP13_ACT3_STAGE1_END"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L38_1.m_CharStrID = "AMY_SIX_NULL_NULL"
L38_1.m_Pos = "L"
L39_1 = "그리고 난 진정하라는 말을 들으면, 왠지 모르게 더 날뛰고 싶어지거든?"
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "それに落ち着けって言われると、なんだかもっと暴れたくなるんだよな。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "Besides, when people tell me to calm down, it just makes me want to go even crazier!"
L38_1.m_Talk_ENG = L39_1
L39_1 = "而且，每次有人叫我冷靜，我就更想瘋狂一下！"
L38_1.m_Talk_TWN = L39_1
L39_1 = "而且每当我听到让我冷静下来的话时，总会莫名其妙地更想发狂呢？"
L38_1.m_Talk_SCN = L39_1
